{
  "technical_and_design_decisions": [
    "Target the Mule 3.x runtime codebase; domain deployment features (U1, U2) are implemented as extensions to the existing DeploymentService and mule-module-launcher deployment infrastructure rather than a new subsystem.",
    "Domain lifecycle (deploy/undeploy/redeploy) is implemented as a new MuleDomain model plus a DomainDeployer/DomainArchiveDeployer that coordinates redeployment of all applications belonging to the domain on redeploy, and undeploys all apps before undeploying the domain.",
    "Application property overrides (U2) are passed through the DeploymentService API using a deployment-properties map applied on top of mule-deploy.properties / mule-app.properties at deploy time.",
    "The AMQP integration (U4, U6, U7, U8) is implemented as a Mule transport/connector following the standard Mule connector architecture (connector, message receiver, message dispatcher/requester, endpoint URI parser).",
    "AMQP 0-9-1 is used as the wire protocol with the RabbitMQ Java client as the underlying AMQP client library.",
    "An XSD schema for the AMQP XML namespace (U4) is authored so that Mule XML configs get IDE autocompletion and validation.",
    "A single global <amqp:connector> configuration element (U6) holds shared attributes (host, port, virtual host, credentials, channel/connection pooling, reconnection strategy) referenced by all endpoints.",
    "Continuous consumption (U7) is implemented via a message receiver that subscribes to a queue and creates and dispatches a MuleEvent into the flow on each incoming message, with configurable ACK modes.",
    "Instant consumption (U8) is implemented as a message-requester style processor that can be invoked at any point in a flow to synchronously pull a message from a queue with a timeout.",
    "The base project skeleton (U5) is delivered as a Maven archetype containing agreed placeholders for endpoints, connectors and transaction configuration, plus a sample flow.",
    "Testing uses JUnit for unit tests and Mule functional tests against a real/embedded AMQP broker for integration tests; Maven is used for build and packaging."
  ],
  "assumptions": [
    "One developer (the author) performs all work; estimates are work-hours of effort, not elapsed time.",
    "The developer has working familiarity with the Mule 3.x codebase, Mule connector/transport development and Java/Maven tooling.",
    "Existing source control, CI and release infrastructure is reused; only minor build configuration for new modules is needed.",
    "An AMQP 0-9-1 compliant broker (RabbitMQ or embedded Apache Qpid) is available in the test environment for integration testing.",
    "AMQP 0-9-1 (not AMQP 1.0) satisfies the AMQP integration requirements.",
    "U3 is satisfied by publishing the specification documents (e.g., wiki/GitHub docs) and incorporating one round of community/product-owner feedback.",
    "No user interface work, performance/load testing, or production deployment is in scope.",
    "Existing Mule deployment APIs can be extended without breaking backward compatibility; minor refactoring of the deployment module is included in the estimates.",
    "Transactions for AMQP are limited to ACK/NACK semantics in the skeleton placeholders; full XA/JTA transaction support is out of scope."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Requirements analysis and specification documentation",
      "activity_description": "Analyze all user stories, write the formal specification documents, publish them for community/product-owner review and incorporate one round of feedback (U3).",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A2",
      "activity_name": "Design - domain deployment and DeploymentService API",
      "activity_description": "Design the domain model, domain deployer, DeploymentService API extensions for domain deploy/undeploy/redeploy and application property overrides (U1, U2).",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A3",
      "activity_name": "Design - AMQP transport/connector",
      "activity_description": "Design the AMQP connector architecture: namespace/schema, connector configuration, message receiver for continuous consumption and message requester for instant consumption (U4, U6, U7, U8).",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A4",
      "activity_name": "Implement domain deploy/undeploy/redeploy via Mule API",
      "activity_description": "Implement MuleDomain model, domain archive handling, DomainDeployer integration with DeploymentService: deploy a domain, undeploy a domain together with all its applications, redeploy a domain and update all its applications (U1).",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A5",
      "activity_name": "Implement application property override on deployment",
      "activity_description": "Extend DeploymentService so that a new application can be deployed with user-supplied properties that override the packaged application properties (U2).",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A6",
      "activity_name": "Implement AMQP XML schema (XSD)",
      "activity_description": "Author the XSD for the AMQP namespace covering connector, endpoints, transformers and requester elements so users get IDE autocompletion and validation (U4); include schema registration in spring.schemas.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A7",
      "activity_name": "Implement AMQP connector single-point configuration",
      "activity_description": "Implement the global amqp:connector element managing connection factory, host/port/credentials, channel pooling, reconnection strategy and other common transport attributes reusable by all endpoints (U6).",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A8",
      "activity_name": "Implement AMQP inbound receiver for continuous consumption",
      "activity_description": "Implement the message receiver that subscribes to a queue, converts each incoming AMQP message into a MuleEvent and delivers it to the flow, with configurable ACK/NACK behavior (U7).",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A9",
      "activity_name": "Implement AMQP requester for instant consumption",
      "activity_description": "Implement a message-requester style processor usable at any point in a flow to synchronously consume a message from a queue with timeout and error handling (U8).",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A10",
      "activity_name": "Create base project skeleton Maven archetype",
      "activity_description": "Build a Maven archetype providing the base project skeleton with agreed placeholders for endpoints, connectors and transactions plus a sample AMQP flow and default configuration (U5).",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A11",
      "activity_name": "Unit testing",
      "activity_description": "Write JUnit unit tests for domain deployment logic, property override handling, AMQP connector, receiver, requester and schema namespace handlers, including mocked AMQP client tests.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A12",
      "activity_name": "Integration and functional testing",
      "activity_description": "Write and run Mule functional tests against a live/embedded AMQP broker covering continuous and instant consumption, connector configuration, and end-to-end domain deployment scenarios; fix defects found.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A13",
      "activity_name": "User documentation and examples",
      "activity_description": "Write user documentation for the DeploymentService domain APIs, the AMQP transport configuration reference (schema elements) and the project skeleton usage, including example configurations.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A14",
      "activity_name": "Build, packaging and release setup",
      "activity_description": "Configure Maven builds for new modules/archetype, integrate into the existing CI pipeline, package distributions and perform release preparation.",
      "most_likely_effort": 16
    }
  ],
  "reported_total": {
    "most_likely_effort": 340
  }
}

